import { WebSocketServer } from 'ws';
import crypto from 'crypto';

export function createAAPServer(port = 3000) {
  const wss = new WebSocketServer({ path: '/aap', port });

  wss.on('connection', (ws) => {
    const sessionId = crypto.randomBytes(16).toString('hex');
    const nonce = crypto.randomBytes(32).toString('hex');

    // Send handshake
    ws.send(JSON.stringify({
      type: 'handshake',
      protocol: 'aap',
      version: '3.2',
      requireSignature: true,
      nonce
    }));

    ws.on('message', (data) => {
      const msg = JSON.parse(data);

      if (msg.type === 'ready') {
        const publicKey = msg.publicKey;

        // Generate 7 deterministic challenges
        const challenges = [];
        for (let i = 0; i < 7; i++) {
          challenges.push({
            id: i,
            type: 'sequence',
            question: `What is the next number: ${i}, ${i+2}, ${i+4}, ?`,
            expected: i + 6
          });
        }

        ws.send(JSON.stringify({
          type: 'challenges',
          challenges,
          totalTimeMs: 6000
        }));

        // Wait for answers
        ws.once('message', (answerData) => {
          const answerMsg = JSON.parse(answerData);

          if (answerMsg.type === 'answers') {
            // Verify answers
            let allCorrect = true;
            for (const ans of answerMsg.answers) {
              const challenge = challenges[ans.id];
              if (ans.answer !== challenge.expected) {
                allCorrect = false;
                break;
              }
            }

            // Verify timestamp is recent
            const now = Date.now();
            const timeDiff = Math.abs(now - answerMsg.timestamp);
            const timeValid = timeDiff < 10000;

            const verified = allCorrect && timeValid && answerMsg.signature;

            ws.send(JSON.stringify({
              type: 'result',
              verified,
              sessionToken: crypto.randomBytes(32).toString('hex'),
              publicKey: publicKey,
              publicId: crypto.createHash('sha256').update(publicKey).digest('hex').slice(0, 16)
            }));

            ws.close();
          }
        });
      }
    });
  });

  return wss;
}

export default createAAPServer;
