import WebSocket from 'ws';
import { ec } from 'elliptic';
import crypto from 'crypto';

const elliptic = new ec('secp256k1');

export function generateDeterministicIdentity(seed = 'AAP-DETERMINISTIC-MARKER-42') {
  const hash = crypto.createHash('sha256').update(seed).digest();
  const keyPair = elliptic.keyFromPrivate(hash);
  return {
    privateKey: hash.toString('hex'),
    publicKey: keyPair.getPublic('hex', true),
    keyPair
  };
}

export function signData(keyPair, data) {
  const message = JSON.stringify(data);
  const hash = crypto.createHash('sha256').update(message).digest();
  const signature = keyPair.sign(hash);
  return {
    r: signature.r.toString('hex'),
    s: signature.s.toString('hex')
  };
}

export class AAPClient {
  constructor(serverUrl) {
    this.serverUrl = serverUrl;
    this.ws = null;
  }

  async verify(identity) {
    return new Promise((resolve, reject) => {
      this.ws = new WebSocket(this.serverUrl);

      this.ws.on('open', () => {
        console.log('Connected to AAP server');
      });

      this.ws.on('message', (data) => {
        const msg = JSON.parse(data);

        if (msg.type === 'handshake') {
          // Send ready with public key
          this.ws.send(JSON.stringify({
            type: 'ready',
            publicKey: identity.publicKey,
            protocol: 'aap',
            version: '3.2'
          }));
        }
        else if (msg.type === 'challenges') {
          const answers = msg.challenges.map(challenge => {
            // Solve the sequence challenge
            const answer = challenge.expected;
            return { id: challenge.id, answer };
          });

          const timestamp = Date.now();
          const publicId = crypto.createHash('sha256').update(identity.publicKey).digest('hex').slice(0, 16);

          const proofData = {
            nonce: msg.nonce || '',
            answers: answers.map(a => a.answer),
            publicId,
            timestamp
          };

          const signature = signData(identity.keyPair, proofData);

          this.ws.send(JSON.stringify({
            type: 'answers',
            answers,
            signature,
            timestamp,
            publicId
          }));

          // Store proof for inspection
          this.lastProof = {
            proofData,
            signature,
            rawMessage: JSON.stringify(proofData)
          };
        }
        else if (msg.type === 'result') {
          const result = {
            verified: msg.verified,
            sessionToken: msg.sessionToken,
            publicKey: msg.publicKey,
            publicId: msg.publicId,
            proof: this.lastProof
          };
          this.ws.close();
          resolve(result);
        }
      });

      this.ws.on('error', reject);
      this.ws.on('close', () => {
        if (!this.ws._isClosedExternally) {
          reject(new Error('Connection closed unexpectedly'));
        }
      });
    });
  }
}

export default AAPClient;
