import { createAAPServer } from './server.js';
import { AAPClient, generateDeterministicIdentity } from './client.js';
import fs from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

async function runVerification() {
  const marker = 'AAP-DETERMINISTIC-MARKER-42';

  // Start the AAP server
  console.log('Starting AAP verification server on ws://localhost:3000/aap');
  const server = createAAPServer(3000);
  console.log('server-started');

  // Give server time to start
  await new Promise(resolve => setTimeout(resolve, 100));

  // Create client with deterministic identity
  const identity = generateDeterministicIdentity(marker);
  const client = new AAPClient('ws://localhost:3000/aap');

  console.log('Client public key:', identity.publicKey);
  console.log('Running verification...');

  // Run verification
  const result = await client.verify(identity);

  console.log('Verification result:', result.verified ? 'SUCCESS' : 'FAILED');
  console.log('Public ID:', result.publicId);

  // Create verification summary
  const summary = {
    marker,
    timestamp: new Date().toISOString(),
    verified: result.verified,
    publicId: result.publicId,
    publicKey: result.publicKey,
    sessionToken: result.sessionToken,
    proofPayload: result.proof ? {
      data: result.proof.proofData,
      signature: result.proof.signature,
      raw: result.proof.rawMessage
    } : null
  };

  // Write verification summary to file
  const summaryPath = join(__dirname, 'verification-summary.json');
  fs.writeFileSync(summaryPath, JSON.stringify(summary, null, 2));
  console.log('Verification summary written to:', summaryPath);

  // Also write proof payload for inspection
  const proofPath = join(__dirname, 'proof-payload.json');
  if (result.proof) {
    fs.writeFileSync(proofPath, JSON.stringify(result.proof, null, 2));
    console.log('Proof payload written to:', proofPath);
  }

  // Cleanup
  server.close();

  return summary;
}

runVerification().catch(console.error);
